import { Box, Grid, IconButton, Tooltip, Typography } from '@mui/material';
import { alpha } from '@mui/material/styles';
import React, { useState } from 'react';
import dayjs from 'dayjs';
import DeleteIcon from '@mui/icons-material/Delete';
import HistoryIcon from '@mui/icons-material/History';
import DeleteTreatments from './DeleteTreatments';
import { IDentalTreatmentType, ITreatments } from '../../../../core/Interface/treatment.interface';

const QUADRANT_MAP = [
  { prefix: 'UR', teeth: [1, 2, 3, 4, 5, 6, 7, 8] },
  { prefix: 'UL', teeth: [9, 10, 11, 12, 13, 14, 15, 16] },
  { prefix: 'LR', teeth: [17, 18, 19, 20, 21, 22, 23, 24] },
  { prefix: 'LL', teeth: [25, 26, 27, 28, 29, 30, 31, 32] },
];

const formatTreatedTeeth = (treatedTeeth: string): string => {
  const teeth = treatedTeeth.split(',').map((n) => parseInt(n.trim(), 10)).filter(Boolean);
  const parts = QUADRANT_MAP
    .map(({ prefix, teeth: qt }) => {
      const matched = qt.filter((n) => teeth.includes(n));
      return matched.length ? `${prefix}: ${matched.join(', ')}` : null;
    })
    .filter(Boolean);
  return parts.length ? parts.join(' · ') : treatedTeeth;
};

const TEAL = '#0F8B8D';
const NAVY = '#0F1D4D';

const ACCENT_COLORS = [
  '#F97316', '#06B6D4', '#8B5CF6', '#22C55E',
  '#0EA5E9', '#EC4899', '#F59E0B', '#14B8A6',
];

const PatientHistory = ({
  treatements,
  dentalTreatmentTypes = [],
}: {
  treatements?: {
    id: string;
    dissese: string;
    medition: string;
    dateTime: string;
    amount: string;
    createdDate?: string;
    treatedTeeth?: string;
    tretmentType?: string;
  }[];
  dentalTreatmentTypes?: IDentalTreatmentType[];
}) => {
  const [deleteOpen, setDeleteOpen] = useState(false);
  // eslint-disable-next-line max-len
  const [treatment, setTreatmentData] = useState<ITreatments | undefined>(undefined);

  const canBeDelete = (date?: string): boolean =>
    dayjs(new Date()).isSame(dayjs(date), 'day');

  if (!treatements || treatements.length === 0) return null;

  return (
    <Box sx={{ mt: 3 }}>
      {/* Section header */}
      <Box
        sx={{
          alignItems: 'center',
          display: 'flex',
          gap: 1.5,
          mb: 2,
        }}
      >
        <Box
          sx={{
            alignItems: 'center',
            background: alpha(TEAL, 0.1),
            border: `1px solid ${alpha(TEAL, 0.2)}`,
            borderRadius: '8px',
            display: 'flex',
            height: 36,
            justifyContent: 'center',
            width: 36,
          }}
        >
          <HistoryIcon sx={{ color: TEAL, fontSize: 18 }} />
        </Box>
        <Box>
          <Typography
            sx={{ color: NAVY, fontSize: 16, fontWeight: 800, lineHeight: 1.2 }}
          >
            Treatment History
          </Typography>
          <Typography sx={{ color: alpha(NAVY, 0.45), fontSize: 12 }}>
            {treatements.length} record{treatements.length !== 1 ? 's' : ''} found
          </Typography>
        </Box>
      </Box>

      {/* Cards grid */}
      <Grid
        container
        spacing={2}
      >
        {treatements.map((item, index) => {
          const accent = ACCENT_COLORS[index % ACCENT_COLORS.length];
          return (
            <Grid
              item
              key={item.id}
              lg={4}
              md={6}
              sm={12}
              xs={12}
            >
              <Box
                sx={{
                  background:
                    `linear-gradient(145deg, rgba(255,255,255,0.98) 0%, ${alpha(accent, 0.05)} 100%)`,
                  border: `1px solid ${alpha(accent, 0.22)}`,
                  borderRadius: '12px',
                  boxShadow: `0 2px 12px ${alpha(NAVY, 0.06)}`,
                  height: '100%',
                  overflow: 'hidden',
                  position: 'relative',
                }}
              >
                {/* accent top bar */}
                <Box
                  sx={{
                    background:
                      `linear-gradient(90deg, ${accent} 0%, ${alpha(accent, 0.4)} 100%)`,
                    height: 3,
                  }}
                />

                <Box sx={{ p: 2 }}>
                  {/* date + delete */}
                  <Box
                    sx={{
                      alignItems: 'center',
                      display: 'flex',
                      justifyContent: 'space-between',
                      mb: 1.5,
                    }}
                  >
                    <Box
                      sx={{
                        background: alpha(accent, 0.1),
                        border: `1px solid ${alpha(accent, 0.2)}`,
                        borderRadius: '20px',
                        color: accent,
                        fontSize: 11,
                        fontWeight: 700,
                        px: 1.25,
                        py: 0.25,
                      }}
                    >
                      {dayjs(item.dateTime).format('MMM D, YYYY')}
                    </Box>

                    {canBeDelete(item?.createdDate) && (
                      <Tooltip title="Delete treatment">
                        <IconButton
                          onClick={() => {
                            setTreatmentData(item);
                            setDeleteOpen(true);
                          }}
                          size="small"
                          sx={{
                            background: alpha('#DC2626', 0.08),
                            borderRadius: '6px',
                            height: 28,
                            width: 28,
                            '&:hover': { background: alpha('#DC2626', 0.15) },
                          }}
                        >
                          <DeleteIcon
                            sx={{ color: '#DC2626', fontSize: 15 }}
                          />
                        </IconButton>
                      </Tooltip>
                    )}
                  </Box>

                  {/* Treatment Type */}
                  {item.tretmentType && (
                    <>
                      <SectionLabel
                        accent={accent}
                        label="Type of Treatment"
                      />
                      <Typography
                        sx={{
                          color: NAVY,
                          fontSize: 13,
                          fontWeight: 500,
                          lineHeight: 1.4,
                          mb: 1.5,
                        }}
                      >
                        {dentalTreatmentTypes.find(
                          (dt) => String(dt.key) === String(item.tretmentType)
                        )?.value ?? item.tretmentType}
                      </Typography>
                    </>
                  )}

                  {/* Treated Teeth */}
                  {item.treatedTeeth && (
                    <>
                      <SectionLabel
                        accent={accent}
                        label="Treated Teeth"
                      />
                      <Typography
                        sx={{
                          color: NAVY,
                          fontSize: 13,
                          fontWeight: 500,
                          lineHeight: 1.4,
                          mb: 1.5,
                        }}
                      >
                        {formatTreatedTeeth(item.treatedTeeth)}
                      </Typography>
                    </>
                  )}

                  {/* Disease */}
                  <SectionLabel
                    accent={accent}
                    label="Disease"
                  />
                  <Typography
                    sx={{
                      color: NAVY,
                      fontSize: 13,
                      fontWeight: 500,
                      lineHeight: 1.4,
                      mb: 1.5,
                    }}
                  >
                    {item.dissese || '—'}
                  </Typography>

                  {/* Medication */}
                  <SectionLabel
                    accent={accent}
                    label="Medication"
                  />
                  <Typography
                    sx={{
                      color: NAVY,
                      fontSize: 13,
                      fontWeight: 500,
                      lineHeight: 1.4,
                      mb: 1.5,
                    }}
                  >
                    {item.medition || '—'}
                  </Typography>

                  {/* Amount */}
                  <Box
                    sx={{
                      alignItems: 'center',
                      background: alpha(accent, 0.06),
                      borderRadius: '8px',
                      display: 'flex',
                      justifyContent: 'space-between',
                      mt: 1,
                      px: 1.5,
                      py: 1,
                    }}
                  >
                    <Typography
                      sx={{
                        color: alpha(NAVY, 0.5),
                        fontSize: 11,
                        fontWeight: 700,
                        letterSpacing: '0.5px',
                        textTransform: 'uppercase',
                      }}
                    >
                      Amount
                    </Typography>
                    <Typography
                      sx={{ color: accent, fontSize: 15, fontWeight: 800 }}
                    >
                      LKR {item.amount}
                    </Typography>
                  </Box>
                </Box>
              </Box>
            </Grid>
          );
        })}
      </Grid>

      {deleteOpen && (
        <DeleteTreatments
          data={treatment}
          handleCloseDialog={() => setDeleteOpen(false)}
          openModel={deleteOpen}
          title="Delete Treatment"
        />
      )}
    </Box>
  );
};

// eslint-disable-next-line react/no-multi-comp
const SectionLabel = ({
  label,
  accent,
}: {
  label: string;
  accent: string;
}) => (
  <Typography
    sx={{
      color: accent,
      fontSize: 10,
      fontWeight: 700,
      letterSpacing: '0.5px',
      mb: 0.25,
      textTransform: 'uppercase',
    }}
  >
    {label}
  </Typography>
);

export default PatientHistory;
