import React, { useMemo, useState } from 'react';

import {
  Box,
  Button,
  CircularProgress,
  Grid,
  InputAdornment,
  MenuItem,
  Select,
  SelectChangeEvent,
  TextField,
  Typography,
} from '@mui/material';
import { alpha } from '@mui/material/styles';
import useUser from '../../../../core/hooks/useUser';
import { useTranslation } from 'react-i18next';
import { useFormik } from 'formik';
import { useNotifier } from '../../../../core/Notifier';
import SearchIcon from '@mui/icons-material/Search';
import MedicalServicesOutlinedIcon from '@mui/icons-material/MedicalServicesOutlined';
import PatientBasicCard from './PatientBasicCard';
import AddIcon from '@mui/icons-material/Add';
import NewPatient from './NewPatient';
import {
  useGetPatientByIdQuery,
  useRegisterTreatmentMutation,
  useGetReferenceDataQuery,
} from '../../../posApi';
import PatientHistory from './PatientHistory';
import { Privileges } from '../../../../core/types/commonType';
import { IPatientCard } from '../../../../core/Interface/patient.interface';
import {
  IDentalTreatmentType,
  ReferenceData,
} from '../../../../core/Interface/treatment.interface';

const TEAL = '#0F8B8D';
const NAVY = '#0F1D4D';
const MID  = '#1E3A8A';

const fieldSx = {
  '& .MuiOutlinedInput-root': {
    backgroundColor: alpha(TEAL, 0.03),
    borderRadius: '8px',
    '& fieldset': { borderColor: alpha(TEAL, 0.2) },
    '&.Mui-focused fieldset': { borderColor: TEAL },
    '&:hover fieldset': { borderColor: alpha(TEAL, 0.4) },
  },
};

const selectSx = {
  backgroundColor: alpha(TEAL, 0.03),
  borderRadius: '8px',
  width: '100%',
  '& .MuiOutlinedInput-notchedOutline': {
    borderColor: alpha(TEAL, 0.2),
  },
  '&:hover .MuiOutlinedInput-notchedOutline': {
    borderColor: alpha(TEAL, 0.4),
  },
  '&.Mui-focused .MuiOutlinedInput-notchedOutline': {
    borderColor: TEAL,
  },
};

const QUADRANTS: { label: string; teeth: number[]; border: string }[] = [
  {
    label: 'Upper Right',
    teeth: [1, 2, 3, 4, 5, 6, 7, 8],
    border: 'borderBottom borderRight',
  },
  {
    label: 'Upper Left',
    teeth: [9, 10, 11, 12, 13, 14, 15, 16],
    border: 'borderBottom borderLeft',
  },
  {
    label: 'Lower Right',
    teeth: [17, 18, 19, 20, 21, 22, 23, 24],
    border: 'borderTop borderRight',
  },
  {
    label: 'Lower Left',
    teeth: [25, 26, 27, 28, 29, 30, 31, 32],
    border: 'borderTop borderLeft',
  },
];

const TreatmentsView = () => {
  const { t } = useTranslation(['common']);
  const { userHasRight } = useUser();
  const { showErrorMessage, showMessage } = useNotifier();
  const [open, setOpen] = useState(false);
  const [selectedTeeth, setSelectedTeeth] = useState<string[]>([]);
  const [patientNumber, setPatientNumber] = useState<string>('');
  const [registerTreatment, { isLoading: isRegisteringTreatment }] =
    useRegisterTreatmentMutation();
  const { data, isFetching } = useGetPatientByIdQuery(
    patientNumber.split('_')[0],
    { skip: !patientNumber }
  );
  const { data: refData } = useGetReferenceDataQuery();

  const patient = useMemo(() => {
    if (!data?.data) {
      return { message: data?.message } as IPatientCard;
    }
    const d = data?.data as IPatientCard;
    return { message: data?.message, ...d } as IPatientCard;
  }, [data]);

  const formik = useFormik({
    initialValues: {
      patientId: '',
      dissese: '',
      amount: '',
      medition: '',
      tretmentType: '',
      treatedTeeth: '',
    },
    onSubmit: async (values) => {
      if (isRegisteringTreatment) return;
      try {
        const response = await registerTreatment({
          ...values,
          patientId: patient.id,
        }).unwrap();
        if (!response.status) {
          showErrorMessage(response.message);
        } else {
          showMessage(response.message);
          formik.resetForm();
          setSelectedTeeth([]);
        }
      } catch (error) {
        showErrorMessage((error as Error).message);
      }
    },
  });

  const formikNew = useFormik({
    initialValues: { patientId: '' },
    onSubmit: async (values) => {
      try {
        setPatientNumber(values.patientId);
      } catch (error) {
        showErrorMessage('Please check you data');
      }
    },
  });

  const handleCheckboxSelect = (value: string) => {
    const index = selectedTeeth.indexOf(value);
    const updatedTeeth =
      index === -1
        ? [...selectedTeeth, value]
        : selectedTeeth.filter((item) => item !== value);
    formik.setFieldValue('treatedTeeth', updatedTeeth.join(', '));
    setSelectedTeeth(updatedTeeth);
  };

  const handleChange = (event: SelectChangeEvent) => {
    formik.setFieldValue('tretmentType', event.target.value);
  };

  const dentalTreatmentTypes = useMemo<IDentalTreatmentType[]>(() => {
    return (refData?.data as ReferenceData)?.dentalTreatmentTypes || [];
  }, [refData]);

  return (
    <Box>
      {/* ── Hero banner ───────────────────────────────────────────── */}
      <Box
        sx={{
          background: `linear-gradient(135deg, ${NAVY} 0%, ${MID} 45%, ${TEAL} 100%)`,
          borderRadius: 2,
          color: '#fff',
          mb: 3,
          overflow: 'hidden',
          position: 'relative',
          px: { xs: 2, md: 3 },
          py: { xs: 1.5, md: 2 },
        }}
      >
        {/* decorative blobs */}
        <Box sx={{ background: 'rgba(255,255,255,0.07)', borderRadius: '50%', height: 220, inset: 'auto -60px -100px auto', pointerEvents: 'none', position: 'absolute', width: 220 }} />
        <Box sx={{ background: 'rgba(255,255,255,0.05)', borderRadius: '50%', height: 260, inset: '-100px auto auto 55%', pointerEvents: 'none', position: 'absolute', width: 260 }} />

        <Box
          sx={{
            alignItems: { xs: 'flex-start', sm: 'center' },
            display: 'flex',
            flexDirection: { xs: 'column', sm: 'row' },
            gap: 2,
            justifyContent: 'space-between',
            position: 'relative',
          }}
        >
          {/* title */}
          <Box sx={{ alignItems: 'center', display: 'flex', gap: 1.5 }}>
            <Box
              sx={{
                alignItems: 'center',
                backdropFilter: 'blur(8px)',
                background: 'rgba(255,255,255,0.14)',
                border: '1px solid rgba(255,255,255,0.18)',
                borderRadius: '10px',
                display: 'flex',
                height: 44,
                justifyContent: 'center',
                width: 44,
              }}
            >
              <MedicalServicesOutlinedIcon sx={{ color: '#fff', fontSize: 22 }} />
            </Box>
            <Box>
              <Typography sx={{ color: '#fff', fontSize: { xs: '1rem', md: '1.2rem' }, fontWeight: 800, letterSpacing: '-0.02em', lineHeight: 1.2 }}>
                Dental
              </Typography>
              <Typography sx={{ color: 'rgba(255,255,255,0.72)', fontSize: '0.78rem' }}>
                Search patient · add treatment · view dental history
              </Typography>
            </Box>
          </Box>

          {/* search + new-patient */}
          <Box sx={{ alignItems: 'center', display: 'flex', gap: 1.5, flexWrap: 'wrap', position: 'relative' }}>
            <form noValidate onSubmit={formikNew.handleSubmit}>
              <Box sx={{ alignItems: 'center', display: 'flex', gap: 1 }}>
                <TextField
                  InputProps={{
                    startAdornment: (
                      <InputAdornment position="start">
                        <SearchIcon sx={{ color: alpha('#fff', 0.6), fontSize: 18 }} />
                      </InputAdornment>
                    ),
                    sx: {
                      color: '#fff',
                      '& .MuiOutlinedInput-notchedOutline': { borderColor: 'rgba(255,255,255,0.35)' },
                      '&:hover .MuiOutlinedInput-notchedOutline': { borderColor: 'rgba(255,255,255,0.6)' },
                      '&.Mui-focused .MuiOutlinedInput-notchedOutline': { borderColor: '#fff' },
                      '& input::placeholder': { color: 'rgba(255,255,255,0.5)' },
                    },
                  }}
                  autoComplete="off"
                  name="patientId"
                  onChange={formikNew.handleChange}
                  placeholder="Patient Number"
                  size="small"
                  sx={{ width: 240 }}
                  value={formikNew.values.patientId}
                  variant="outlined"
                />
                <Button
                  disabled={isFetching}
                  sx={{
                    background: 'rgba(255,255,255,0.18)',
                    backdropFilter: 'blur(4px)',
                    border: '1px solid rgba(255,255,255,0.3)',
                    borderRadius: '8px',
                    color: '#fff',
                    fontWeight: 700,
                    height: 40,
                    px: 2,
                    '&:hover': { background: 'rgba(255,255,255,0.28)' },
                    '&:disabled': { opacity: 0.6 },
                  }}
                  type="submit"
                  variant="outlined"
                >
                  {isFetching ? <CircularProgress size={16} sx={{ color: '#fff' }} /> : t('common:search')}
                </Button>
              </Box>
            </form>

            {userHasRight(Privileges.PatientAdd) && (
              <Button
                onClick={() => setOpen(true)}
                startIcon={<AddIcon />}
                sx={{
                  background: 'linear-gradient(135deg, #2563EB 0%, #1d4ed8 100%)',
                  borderRadius: '8px',
                  boxShadow: `0 4px 14px ${alpha('#2563EB', 0.45)}`,
                  color: '#fff',
                  fontWeight: 700,
                  height: 40,
                  px: 2.5,
                  '&:hover': { background: 'linear-gradient(135deg, #1d4ed8 0%, #1e40af 100%)' },
                }}
                variant="contained"
              >
                {t('common:create')} Patient
              </Button>
            )}
          </Box>
        </Box>
      </Box>

      {/* ── Main content ─────────────────────────────────────── */}
      <Grid
        container
        justifyContent="space-around"
        spacing={2}
      >
        <PatientBasicCard
          address={patient?.address || ''}
          age={patient?.age}
          dateOfBirth={patient?.dateOfBirth}
          id={patient?.id}
          message={patient?.message}
          mobile={patient?.mobile}
          name={patient?.name}
          patientNumber={patient?.patientNumber}
        />

        <Grid
          item
          lg={8}
          sm={12}
          xs={12}
        >
          <Box
            sx={{
              background: '#fff',
              border: `1px solid ${alpha(TEAL, 0.15)}`,
              borderRadius: '12px',
              boxShadow: `0 4px 24px ${alpha(NAVY, 0.05)}`,
              overflow: 'hidden',
            }}
          >
            {/* card accent bar */}
            <Box
              sx={{
                background:
                  `linear-gradient(90deg, ${TEAL} 0%, ${alpha(TEAL, 0.5)} 100%)`,
                height: 3,
              }}
            />

            <form noValidate onSubmit={formik.handleSubmit}>
              <Grid
                container
                spacing={2}
                sx={{ p: 2.5 }}
              >
                {/* Treatment type */}
                <GridItem>
                  <FieldLabel>Type of Treatment</FieldLabel>
                  <Select
                    {...formik.getFieldProps('tretmentType')}
                    onChange={handleChange}
                    size="small"
                    sx={selectSx}
                    value={formik.values.tretmentType}
                  >
                    {dentalTreatmentTypes.map(
                      ({ key, value }: IDentalTreatmentType) => (
                        <MenuItem
                          key={key}
                          value={String(key)}
                        >
                          {value}
                        </MenuItem>
                      )
                    )}
                  </Select>
                </GridItem>

                {/* ── Tooth chart ────────────────────────────────── */}
                <GridItem>
                  <FieldLabel>Tooth Chart</FieldLabel>

                  {/* Selected teeth summary */}
                  {selectedTeeth.length > 0 && (
                    <Box
                      sx={{
                        alignItems: 'center',
                        background: alpha(TEAL, 0.06),
                        border: `1px solid ${alpha(TEAL, 0.2)}`,
                        borderRadius: '8px',
                        display: 'flex',
                        flexWrap: 'wrap',
                        gap: 1,
                        mb: 1.5,
                        px: 1.5,
                        py: 0.75,
                      }}
                    >
                      <Typography
                        sx={{
                          color: alpha(TEAL, 0.8),
                          fontSize: 10,
                          fontWeight: 700,
                          letterSpacing: '0.5px',
                          textTransform: 'uppercase',
                        }}
                      >
                        Selected:
                      </Typography>
                      {QUADRANTS.map((q) => {
                        const prefix = q.label.split(' ').map((w) => w[0]).join('');
                        const qTeeth = q.teeth
                          .filter((tooth) => selectedTeeth.includes(tooth.toString()))
                          .map((tooth) => tooth.toString());
                        if (qTeeth.length === 0) return null;
                        return (
                          <Box
                            key={q.label}
                            sx={{
                              alignItems: 'center',
                              background: TEAL,
                              borderRadius: '4px',
                              color: '#fff',
                              display: 'flex',
                              fontSize: 10,
                              fontWeight: 800,
                              gap: 0.25,
                              px: 0.75,
                              py: 0.25,
                            }}
                          >
                            <span style={{ opacity: 0.8 }}>{prefix}:</span>
                            <span>{qTeeth.join(', ')}</span>
                          </Box>
                        );
                      })}
                    </Box>
                  )}

                  <Box
                    sx={{
                      background: alpha(TEAL, 0.015),
                      border: `1px solid ${alpha(TEAL, 0.15)}`,
                      borderRadius: '12px',
                      overflow: 'hidden',
                    }}
                  >
                    {/* Legend */}
                    <Box
                      sx={{
                        alignItems: 'center',
                        background: alpha(NAVY, 0.03),
                        borderBottom: `1px solid ${alpha(TEAL, 0.1)}`,
                        display: 'flex',
                        gap: 2,
                        justifyContent: 'center',
                        py: 0.75,
                      }}
                    >
                      <Box
                        sx={{
                          alignItems: 'center',
                          display: 'flex',
                          gap: 0.5,
                        }}
                      >
                        <ToothIcon
                          id="legend-healthy"
                          selected={false}
                          size={14}
                        />
                        <Typography
                          sx={{
                            color: alpha(NAVY, 0.45),
                            fontSize: 10,
                          }}
                        >
                          Healthy
                        </Typography>
                      </Box>
                      <Box
                        sx={{
                          alignItems: 'center',
                          display: 'flex',
                          gap: 0.5,
                        }}
                      >
                        <ToothIcon
                          id="legend-selected"
                          selected
                          size={14}
                        />
                        <Typography
                          sx={{ color: TEAL, fontSize: 10 }}
                        >
                          Selected for treatment
                        </Typography>
                      </Box>
                    </Box>

                    {/* 4 quadrants */}
                    <Grid container>
                      {QUADRANTS.map((q) => {
                        const isRight = q.label.includes('Right');
                        const isUpper = q.label.includes('Upper');
                        return (
                          <Grid
                            item
                            key={q.label}
                            lg={6}
                            sm={6}
                            sx={{
                              borderBottom: isUpper
                                ? `2px solid ${alpha(TEAL, 0.18)}`
                                : undefined,
                              borderLeft: !isRight
                                ? `2px solid ${alpha(TEAL, 0.18)}`
                                : undefined,
                              borderRight: isRight
                                ? `2px solid ${alpha(TEAL, 0.18)}`
                                : undefined,
                              borderTop: !isUpper
                                ? `2px solid ${alpha(TEAL, 0.18)}`
                                : undefined,
                              p: 1.5,
                            }}
                            xs={6}
                          >
                            <Typography
                              sx={{
                                color: TEAL,
                                fontSize: 10,
                                fontWeight: 700,
                                letterSpacing: '0.4px',
                                mb: 1,
                                textTransform: 'uppercase',
                              }}
                            >
                              {q.label}
                            </Typography>
                            <Box
                              sx={{
                                display: 'flex',
                                flexWrap: 'wrap',
                                gap: '4px',
                              }}
                            >
                              {q.teeth.map((v) => (
                                <ToothButton
                                  key={v}
                                  number={v}
                                  onClick={() =>
                                    handleCheckboxSelect(v.toString())
                                  }
                                  selected={selectedTeeth.includes(
                                    v.toString()
                                  )}
                                />
                              ))}
                            </Box>
                          </Grid>
                        );
                      })}
                    </Grid>
                  </Box>
                </GridItem>

                {/* Disease */}
                <GridItem>
                  <FieldLabel>Disease</FieldLabel>
                  <TextField
                    autoComplete="off"
                    fullWidth
                    multiline
                    placeholder="Disease"
                    rows={2}
                    size="small"
                    sx={fieldSx}
                    {...formik.getFieldProps('dissese')}
                  />
                </GridItem>

                {/* Medication */}
                <GridItem>
                  <FieldLabel>Medication</FieldLabel>
                  <TextField
                    autoComplete="off"
                    fullWidth
                    multiline
                    placeholder="Medication"
                    rows={2}
                    size="small"
                    sx={fieldSx}
                    {...formik.getFieldProps('medition')}
                  />
                </GridItem>

                {/* Amount */}
                <GridItem>
                  <FieldLabel>Amount</FieldLabel>
                  <TextField
                    autoComplete="off"
                    fullWidth
                    placeholder="Amount"
                    size="small"
                    sx={fieldSx}
                    type="number"
                    inputProps={{ step: 'any' }}
                    {...formik.getFieldProps('amount')}
                  />
                </GridItem>

                {/* Submit */}
                <GridItem
                  sx={{
                    alignItems: 'flex-end',
                    display: 'flex',
                    flexDirection: 'column',
                    pt: 1,
                  }}
                >
                  <Button
                    disabled={!patient?.patientNumber || isRegisteringTreatment}
                    sx={{
                      background: patient?.patientNumber
                        ? `linear-gradient(135deg, ${TEAL} 0%, ${MID} 100%)`
                        : undefined,
                      borderRadius: '8px',
                      boxShadow: patient?.patientNumber
                        ? `0 4px 14px ${alpha(TEAL, 0.4)}`
                        : undefined,
                      color: '#fff',
                      fontWeight: 700,
                      height: 42,
                      minWidth: 130,
                      '&:hover': {
                        background:
                          `linear-gradient(135deg, ${MID} 0%, ${NAVY} 100%)`,
                      },
                      '&.Mui-disabled': {
                        background: alpha(NAVY, 0.1),
                        color: alpha(NAVY, 0.35),
                      },
                    }}
                    type="submit"
                    variant="contained"
                  >
                    {isRegisteringTreatment ? (
                      <CircularProgress
                        size={18}
                        sx={{ color: '#fff' }}
                      />
                    ) : (
                      t('common:submit')
                    )}
                  </Button>
                </GridItem>
              </Grid>
            </form>
          </Box>
        </Grid>
      </Grid>

      <PatientHistory
        dentalTreatmentTypes={dentalTreatmentTypes}
        treatements={patient.treatements}
      />

      {open && (
        <NewPatient
          data={undefined}
          handleCloseDialog={() => setOpen(false)}
          openModel={open}
          title={false ? 'Edit Patient' : 'Create New Patient'}
        />
      )}
    </Box>
  );
};

// eslint-disable-next-line react/no-multi-comp
const GridItem = ({ ...rest }) => (
  <Grid
    item
    lg={12}
    sm={12}
    sx={{ alignItems: 'start', display: 'flex', flexDirection: 'column' }}
    xs={12}
    {...rest}
  />
);

// eslint-disable-next-line react/no-multi-comp
const FieldLabel = ({ children }: { children: React.ReactNode }) => (
  <Typography
    sx={{
      color: alpha(NAVY, 0.5),
      fontSize: 11,
      fontWeight: 700,
      letterSpacing: '0.5px',
      mb: 0.75,
      textTransform: 'uppercase',
    }}
  >
    {children}
  </Typography>
);

// eslint-disable-next-line react/no-multi-comp
type ToothType = 'incisor' | 'canine' | 'premolar' | 'molar';

const getToothType = (num: number): ToothType => {
  if ([7, 8, 9, 10, 23, 24, 25, 26].includes(num)) return 'incisor';
  if ([6, 11, 22, 27].includes(num)) return 'canine';
  if ([4, 5, 12, 13, 20, 21, 28, 29].includes(num)) return 'premolar';
  return 'molar';
};

/* Crown SVG paths — viewBox 0 0 28 44 */
const CROWN_PATHS: Record<ToothType, string> = {
  /* Incisor: broad chisel crown, flatter top arc (ctrl y=5) */
  incisor:  'M5,24 C5,18 7,10 9,8 Q14,5 19,8 C21,10 23,18 23,24 Q19,27 14,27 Q9,27 5,24 Z',
  /* Canine: narrow triangular crown, sharp cusp tip (ctrl y=1) */
  canine:   'M8,23 C8,16 9,8 10,6 Q14,1 18,6 C19,8 20,16 20,23 Q16,27 14,27 Q12,27 8,23 Z',
  /* Premolar: two cusps — buccal (ctrl y=2) taller, lingual (ctrl y=4) shorter */
  premolar: 'M5,24 C5,16 7,8 9,6 Q11,2 13,6 Q15,4 17,6 C21,10 23,16 23,24 Q19,27 14,27 Q9,27 5,24 Z',
  /* Molar: wide crown, two buccal cusps (ctrl y=2), smooth cervical arch */
  molar:    'M2,24 C2,16 4,8 7,6 Q9,2 11,7 Q14,9 17,6 Q19,2 21,7 C24,9 26,16 26,24 C24,28 4,28 2,24 Z',
};

/* Root SVG paths — one entry per root */
const ROOT_PATHS: Record<ToothType, string[]> = {
  incisor:  ['M9,27 L8,40 C9,44 19,44 20,40 L19,27 Z'],
  canine:   ['M10,27 L9,40 C10,44 18,44 19,40 L18,27 Z'],
  premolar: ['M10,27 L9,40 C10,44 18,44 18,40 L18,27 Z'],
  molar:    ['M4,27 L3,40 C4,44 11,44 12,40 L12,27 Z', 'M16,27 L16,40 C16,44 24,44 24,40 L24,27 Z'],
};

const GUM_SHADOW: Record<ToothType, string> = {
  incisor:  'M5,24 Q14,27 23,24',
  canine:   'M8,23 Q14,26 20,23',
  premolar: 'M5,24 Q14,27 23,24',
  molar:    'M3,26 Q14,29 24,26',
};

type ToothHL = { cx: number; cy: number; rx: number; ry: number };
const TOOTH_HIGHLIGHT: Record<ToothType, ToothHL> = {
  incisor:  { cx: 9.5, cy: 12, rx: 2,   ry: 3   },
  canine:   { cx: 10,  cy: 10, rx: 1.5, ry: 3   },
  premolar: { cx: 9,   cy: 11, rx: 1.8, ry: 2.5 },
  molar:    { cx: 7,   cy: 11, rx: 1.8, ry: 3   },
};

// eslint-disable-next-line react/no-multi-comp
const ToothIcon = ({
  id,
  selected,
  size = 22,
  number = 0,
}: {
  id: string;
  selected: boolean;
  size?: number;
  number?: number;
}) => {
  const cg = `tcg-${id}`;
  const rg = `trg-${id}`;
  const sf = `tsf-${id}`;
  const toothType: ToothType = number ? getToothType(number) : 'incisor';

  const eTop  = selected ? '#B8ECEC' : '#FFFFFF';
  const eMid  = selected ? '#1EA8AA' : '#DCF0F6';
  const eEdge = selected ? '#0A6668' : '#A4C8D8';
  const dTop  = selected ? '#5ECECE' : '#F4EAD8';
  const dBot  = selected ? '#0A6668' : '#C8AA88';
  const str   = selected ? '#0A6668' : '#A8C4D0';
  const sdCol = selected ? 'rgba(10,102,104,0.38)' : 'rgba(15,29,77,0.18)';

  const crown     = CROWN_PATHS[toothType];
  const roots     = ROOT_PATHS[toothType];
  const gumShadow = GUM_SHADOW[toothType];
  const hl        = TOOTH_HIGHLIGHT[toothType];

  return (
    <svg
      fill="none"
      height={(size * 44) / 28}
      viewBox="0 0 28 44"
      width={size}
    >
      <defs>
        <radialGradient
          cx="36%"
          cy="22%"
          id={cg}
          r="74%"
        >
          <stop
            offset="0%"
            stopColor={eTop}
          />
          <stop
            offset="46%"
            stopColor={eMid}
          />
          <stop
            offset="100%"
            stopColor={eEdge}
          />
        </radialGradient>
        <linearGradient
          id={rg}
          x1="25%"
          x2="75%"
          y1="0%"
          y2="100%"
        >
          <stop
            offset="0%"
            stopColor={dTop}
          />
          <stop
            offset="100%"
            stopColor={dBot}
          />
        </linearGradient>
        <filter
          height="160%"
          id={sf}
          width="180%"
          x="-40%"
          y="-20%"
        >
          <feDropShadow
            dx="0"
            dy="1.8"
            floodColor={sdCol}
            stdDeviation="1.4"
          />
        </filter>
      </defs>

      {/* Roots rendered behind crown */}
      {roots.map((d, i) => (
        <path
          d={d}
          fill={`url(#${rg})`}
          key={`r${i}`}
          stroke={str}
          strokeLinejoin="round"
          strokeWidth="0.6"
        />
      ))}

      {/* Gum-line ambient occlusion */}
      <path
        d={gumShadow}
        fill="none"
        opacity="0.25"
        stroke="rgba(0,0,0,0.55)"
        strokeLinecap="round"
        strokeWidth="2"
      />

      {/* Crown with drop-shadow */}
      <path
        d={crown}
        fill={`url(#${cg})`}
        filter={`url(#${sf})`}
        stroke={str}
        strokeWidth="0.75"
      />

      {/* Rim light */}
      <ellipse
        cx={hl.cx - 0.5}
        cy={hl.cy + 2}
        fill="none"
        opacity="0.55"
        rx={hl.rx * 0.55}
        ry={hl.ry}
        stroke="rgba(255,255,255,0.9)"
        strokeWidth="0.9"
      />

      {/* Specular highlight */}
      <ellipse
        cx={hl.cx}
        cy={hl.cy}
        fill="rgba(255,255,255,0.78)"
        rx={hl.rx}
        ry={hl.ry}
      />
    </svg>
  );
};

// eslint-disable-next-line react/no-multi-comp
const ToothButton = ({
  number,
  onClick,
  selected,
}: {
  number: number;
  onClick: () => void;
  selected: boolean;
}) => (
  <Box
    onClick={onClick}
    sx={{
      alignItems: 'center',
      borderRadius: '8px',
      cursor: 'pointer',
      display: 'flex',
      flexDirection: 'column',
      gap: '2px',
      p: '4px',
      transition: 'all 0.15s cubic-bezier(0.34,1.56,0.64,1)',
      userSelect: 'none',
      '&:hover': {
        background: selected ? alpha(TEAL, 0.1) : alpha(NAVY, 0.05),
        transform: 'translateY(-3px) scale(1.12)',
      },
      '&:active': { transform: 'translateY(0) scale(0.96)' },
    }}
  >
    <ToothIcon
      id={number.toString()}
      number={number}
      selected={selected}
    />
    <Typography
      sx={{
        color: selected ? TEAL : alpha(NAVY, 0.4),
        fontSize: 9,
        fontWeight: 800,
        lineHeight: 1,
        mt: '1px',
      }}
    >
      {number}
    </Typography>
  </Box>
);

export default TreatmentsView;
