import { Alert, Box, Chip, Divider, Grid, Typography } from '@mui/material';
import { alpha } from '@mui/material/styles';
import React from 'react';
import dayjs from 'dayjs';
import PersonOutlineIcon from '@mui/icons-material/PersonOutline';
import CalendarTodayOutlinedIcon from '@mui/icons-material/CalendarTodayOutlined';
import PhoneOutlinedIcon from '@mui/icons-material/PhoneOutlined';
import HomeOutlinedIcon from '@mui/icons-material/HomeOutlined';
import BadgeOutlinedIcon from '@mui/icons-material/BadgeOutlined';
import EventNoteIcon from '@mui/icons-material/EventNote';
import { IPatientCard } from '../../../../core/Interface/patient.interface';

const DUMMY_APPOINTMENTS = [
  {
    id: 1,
    date: 'Jun 15, 2026',
    time: '10:00 AM',
    treatment: 'Crown Fitting',
    tooth: 'Tooth #14',
    quadrant: 'Upper Molar',
    isNext: true,
  },
  {
    id: 2,
    date: 'Jun 22, 2026',
    time: '2:30 PM',
    treatment: 'Routine Cleaning',
    tooth: 'Tooth #7',
    quadrant: 'Upper Incisor',
    isNext: false,
  },
];

const TEAL = '#0F8B8D';
const NAVY = '#0F1D4D';
const MID  = '#1E3A8A';

const PatientBasicCard = ({
  patientNumber,
  name,
  mobile,
  address,
  message,
  age,
}: IPatientCard) => (
  <Grid
    item
    lg={4}
    sm={12}
    xs={12}
  >
    <Box
      sx={{
        background: '#fff',
        border: `1px solid ${alpha(TEAL, 0.18)}`,
        borderRadius: '12px',
        boxShadow: `0 4px 24px ${alpha(NAVY, 0.06)}`,
        height: '100%',
        minHeight: 320,
        overflow: 'hidden',
      }}
    >
      {/* top accent bar */}
      <Box
        sx={{
          background:
            `linear-gradient(90deg, ${TEAL} 0%, ${alpha(TEAL, 0.5)} 100%)`,
          height: 3,
        }}
      />

      {/* patient avatar area */}
      <Box
        sx={{
          alignItems: 'center',
          background:
            `linear-gradient(135deg, ${alpha(TEAL, 0.06)} 0%, ${alpha(MID, 0.04)} 100%)`,
          borderBottom: `1px solid ${alpha(TEAL, 0.1)}`,
          display: 'flex',
          flexDirection: 'column',
          gap: 1,
          pb: 2,
          pt: 2.5,
        }}
      >
        <Box
          sx={{
            alignItems: 'center',
            background: name
              ? `linear-gradient(135deg, ${TEAL} 0%, ${MID} 100%)`
              : alpha(NAVY, 0.08),
            borderRadius: '50%',
            display: 'flex',
            height: 64,
            justifyContent: 'center',
            width: 64,
          }}
        >
          <PersonOutlineIcon
            sx={{ color: name ? '#fff' : alpha(NAVY, 0.3), fontSize: 32 }}
          />
        </Box>

        {name ? (
          <>
            <Typography
              sx={{
                color: NAVY,
                fontSize: 16,
                fontWeight: 800,
                lineHeight: 1.2,
              }}
            >
              {name}
            </Typography>
            <Chip
              label={`ID: ${patientNumber}`}
              size="small"
              sx={{
                background: alpha(TEAL, 0.1),
                border: `1px solid ${alpha(TEAL, 0.25)}`,
                color: TEAL,
                fontSize: 11,
                fontWeight: 700,
              }}
            />
          </>
        ) : (
          <Typography
            sx={{ color: alpha(NAVY, 0.35), fontSize: 13, fontWeight: 500 }}
          >
            No patient selected
          </Typography>
        )}
      </Box>

      {/* details / state */}
      <Box sx={{ pb: 2.5, pt: 2, px: 2.5 }}>
        {!message && !name && (
          <Alert
            severity="info"
            sx={{ borderRadius: '8px', fontSize: 13 }}
            variant="outlined"
          >
            Search and find the patient
          </Alert>
        )}

        {!name && message && (
          <Alert
            severity="warning"
            sx={{ borderRadius: '8px', fontSize: 13 }}
            variant="outlined"
          >
            {message}
          </Alert>
        )}

        {name && (
          <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1.5 }}>
            <InfoRow
              icon={
                <CalendarTodayOutlinedIcon sx={{ color: TEAL, fontSize: 14 }} />
              }
              label="Date"
              value={dayjs(new Date()).format('MMMM D, YYYY')}
            />
            <InfoRow
              icon={<BadgeOutlinedIcon sx={{ color: TEAL, fontSize: 14 }} />}
              label="Age"
              value={age ? String(age) : '—'}
            />
            <InfoRow
              icon={<PhoneOutlinedIcon sx={{ color: TEAL, fontSize: 14 }} />}
              label="Mobile"
              value={mobile || '—'}
            />
            <InfoRow
              icon={<HomeOutlinedIcon sx={{ color: TEAL, fontSize: 14 }} />}
              label="Address"
              value={address || '—'}
            />
            {message && (
              <Alert
                severity="success"
                sx={{ borderRadius: '8px', fontSize: 12, mt: 0.5 }}
                variant="outlined"
              >
                {message}
              </Alert>
            )}

            <Divider sx={{ borderColor: alpha(TEAL, 0.12) }} />

            {/* ── Appointments ── */}
            <Box>
              <Box
                sx={{
                  alignItems: 'center',
                  display: 'flex',
                  gap: 1,
                  mb: 1.25,
                }}
              >
                <Box
                  sx={{
                    alignItems: 'center',
                    background: alpha('#6366F1', 0.1),
                    border: `1px solid ${alpha('#6366F1', 0.2)}`,
                    borderRadius: '6px',
                    display: 'flex',
                    flexShrink: 0,
                    height: 26,
                    justifyContent: 'center',
                    width: 26,
                  }}
                >
                  <EventNoteIcon sx={{ color: '#6366F1', fontSize: 14 }} />
                </Box>
                <Typography
                  sx={{
                    color: NAVY,
                    fontSize: 11,
                    fontWeight: 700,
                    letterSpacing: '0.5px',
                    textTransform: 'uppercase',
                  }}
                >
                  Appointments
                </Typography>
              </Box>

              <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1 }}>
                {DUMMY_APPOINTMENTS.map((appt) => (
                  <Box
                    key={appt.id}
                    sx={{
                      background: appt.isNext
                        ? `linear-gradient(135deg, ${alpha('#6366F1', 0.07)} 0%, ${alpha('#6366F1', 0.02)} 100%)`
                        : alpha(NAVY, 0.02),
                      border: `1px solid ${appt.isNext ? alpha('#6366F1', 0.2) : alpha(NAVY, 0.08)}`,
                      borderLeft: `3px solid ${appt.isNext ? '#6366F1' : alpha(NAVY, 0.2)}`,
                      borderRadius: '8px',
                      p: 1.25,
                    }}
                  >
                    <Box
                      sx={{
                        alignItems: 'center',
                        display: 'flex',
                        justifyContent: 'space-between',
                        mb: 0.5,
                      }}
                    >
                      <Chip
                        label={appt.isNext ? 'Next' : 'Upcoming'}
                        size="small"
                        sx={{
                          background: appt.isNext ? '#6366F1' : alpha(NAVY, 0.08),
                          borderRadius: '4px',
                          color: appt.isNext ? '#fff' : alpha(NAVY, 0.6),
                          fontSize: 9,
                          fontWeight: 700,
                          height: 16,
                          '& .MuiChip-label': { px: 0.75 },
                        }}
                      />
                      <Typography
                        sx={{
                          color: appt.isNext ? '#6366F1' : alpha(NAVY, 0.45),
                          fontSize: 10,
                          fontWeight: 700,
                        }}
                      >
                        {appt.date}
                      </Typography>
                    </Box>

                    <Typography
                      sx={{
                        color: NAVY,
                        fontSize: 12,
                        fontWeight: 700,
                        lineHeight: 1.3,
                      }}
                    >
                      {appt.treatment}
                    </Typography>

                    <Box
                      sx={{
                        alignItems: 'center',
                        display: 'flex',
                        gap: 0.5,
                        mt: 0.25,
                      }}
                    >
                      <Typography
                        sx={{
                          background: appt.isNext
                            ? alpha('#6366F1', 0.1)
                            : alpha(NAVY, 0.06),
                          borderRadius: '3px',
                          color: appt.isNext ? '#6366F1' : alpha(NAVY, 0.5),
                          fontSize: 10,
                          fontWeight: 600,
                          px: 0.5,
                        }}
                      >
                        {appt.tooth}
                      </Typography>
                      <Typography sx={{ color: alpha(NAVY, 0.35), fontSize: 10 }}>
                        ·
                      </Typography>
                      <Typography sx={{ color: alpha(NAVY, 0.45), fontSize: 10 }}>
                        {appt.quadrant}
                      </Typography>
                      <Typography
                        sx={{
                          color: alpha(NAVY, 0.35),
                          fontSize: 10,
                          ml: 'auto',
                        }}
                      >
                        {appt.time}
                      </Typography>
                    </Box>
                  </Box>
                ))}
              </Box>
            </Box>
          </Box>
        )}
      </Box>
    </Box>
  </Grid>
);

// eslint-disable-next-line react/no-multi-comp
const InfoRow = ({
  icon,
  label,
  value,
}: {
  icon: React.ReactNode;
  label: string;
  value: string;
}) => (
  <Box sx={{ alignItems: 'flex-start', display: 'flex', gap: 1 }}>
    <Box
      sx={{
        alignItems: 'center',
        background: alpha(TEAL, 0.08),
        borderRadius: '6px',
        display: 'flex',
        flexShrink: 0,
        height: 26,
        justifyContent: 'center',
        width: 26,
      }}
    >
      {icon}
    </Box>
    <Box>
      <Typography
        sx={{
          color: alpha(NAVY, 0.45),
          fontSize: 10,
          fontWeight: 700,
          letterSpacing: '0.4px',
          lineHeight: 1,
          textTransform: 'uppercase',
        }}
      >
        {label}
      </Typography>
      <Typography
        sx={{
          color: NAVY,
          fontSize: 13,
          fontWeight: 600,
          lineHeight: 1.3,
          mt: 0.25,
        }}
      >
        {value}
      </Typography>
    </Box>
  </Box>
);

export default PatientBasicCard;
