import * as React from 'react';
import Button from '@mui/material/Button';
import Dialog from '@mui/material/Dialog';
import DialogActions from '@mui/material/DialogActions';
import DialogContent from '@mui/material/DialogContent';
import {
  Box,
  CircularProgress,
  Grid,
  IconButton,
  TextField,
  Typography,
  useMediaQuery,
} from '@mui/material';
import { alpha } from '@mui/material/styles';
import { theme } from '../../../../theme';
import { useFormik } from 'formik';
import { useMemo } from 'react';
import { useSavePatientMutation } from '../../../posApi';
import { useNotifier } from '../../../../core/Notifier';
import { useTranslation } from 'react-i18next';
import { AdapterDayjs } from '@mui/x-date-pickers/AdapterDayjs';
import { LocalizationProvider } from '@mui/x-date-pickers/LocalizationProvider';
import { DatePicker } from '@mui/x-date-pickers/DatePicker';
import { IUserInfo } from '../../../../core/Interface/patient.interface';
import PersonAddAltOutlinedIcon from '@mui/icons-material/PersonAddAltOutlined';
import CloseIcon from '@mui/icons-material/Close';

const TEAL = '#0F8B8D';
const NAVY = '#0F1D4D';
const MID  = '#1E3A8A';

interface INewPatient {
  openModel?: boolean;
  title: string;
  handleCloseDialog: (close: boolean) => void;
  data?: IUserInfo;
}

const NewPatient = ({
  title,
  openModel = true,
  handleCloseDialog,
  data,
}: INewPatient) => {
  const { t } = useTranslation(['common', 'product', 'category']);
  const [open] = React.useState(openModel);
  const isMobile = useMediaQuery(theme.breakpoints.down('md'));
  const [savePatient, { isLoading }] = useSavePatientMutation();
  const { showErrorMessage, showMessage } = useNotifier();

  const handleClose = () => {
    handleCloseDialog(false);
  };

  const formik = useFormik({
    initialValues: {
      name: data?.name,
      mobile: data?.mobile,
      address: data?.address,
      dateOfBirth: data?.dateOfBirth || new Date('2023-12-31'),
      email: '',
    },
    onSubmit: async (values) => {
      try {
        const temData = { ...values, id: data?.id };
        const response = await savePatient(temData).unwrap();
        if (!response.status) {
          showErrorMessage(response.message);
        } else {
          showMessage(response.message);
          handleClose();
        }
      } catch (error) {
        showErrorMessage((error as Error).message);
      }
    },
  });

  const formValid = useMemo(
    () => !(formik.values.name === '' || formik.values.name === undefined),
    [formik],
  );

  const buttonText = data ? t('common:update') : t('common:create');

  return (
    <div>
      <form noValidate onSubmit={formik.handleSubmit}>
        <Dialog
          PaperProps={{
            sx: {
              borderRadius: '16px',
              overflow: 'hidden',
              boxShadow: `0 24px 64px ${alpha(NAVY, 0.22)}`,
            },
          }}
          aria-describedby="alert-dialog-description"
          fullScreen={isMobile}
          fullWidth
          maxWidth="xs"
          open={open}
        >
          {/* ── Gradient header ───────────────────────────────────── */}
          <Box
            sx={{
              background:
                `linear-gradient(135deg, ${NAVY} 0%, ${MID} 50%, ${TEAL} 100%)`,
              overflow: 'hidden',
              position: 'relative',
              px: 3,
              py: 2.5,
            }}
          >
            <Box
              sx={{
                background: 'rgba(255,255,255,0.07)',
                borderRadius: '50%',
                height: 120,
                inset: 'auto -30px -60px auto',
                pointerEvents: 'none',
                position: 'absolute',
                width: 120,
              }}
            />
            <Box
              sx={{
                background: 'rgba(255,255,255,0.05)',
                borderRadius: '50%',
                height: 90,
                inset: '-40px auto auto 55%',
                pointerEvents: 'none',
                position: 'absolute',
                width: 90,
              }}
            />

            <Box
              sx={{
                alignItems: 'center',
                display: 'flex',
                justifyContent: 'space-between',
                position: 'relative',
              }}
            >
              <Box sx={{ alignItems: 'center', display: 'flex', gap: 1.5 }}>
                <Box
                  sx={{
                    alignItems: 'center',
                    backdropFilter: 'blur(8px)',
                    background: 'rgba(255,255,255,0.14)',
                    border: '1px solid rgba(255,255,255,0.2)',
                    borderRadius: '10px',
                    display: 'flex',
                    height: 40,
                    justifyContent: 'center',
                    width: 40,
                  }}
                >
                  <PersonAddAltOutlinedIcon
                    sx={{ color: '#fff', fontSize: 20 }}
                  />
                </Box>
                <Box>
                  <Typography
                    sx={{
                      color: '#fff',
                      fontSize: '1rem',
                      fontWeight: 800,
                      letterSpacing: '-0.01em',
                      lineHeight: 1.2,
                    }}
                  >
                    {title}
                  </Typography>
                  <Typography
                    sx={{ color: 'rgba(255,255,255,0.65)', fontSize: '0.75rem' }}
                  >
                    {data ? 'Update patient details' : 'Register a new patient'}
                  </Typography>
                </Box>
              </Box>

              <IconButton
                onClick={handleClose}
                size="small"
                sx={{
                  background: 'rgba(255,255,255,0.12)',
                  border: '1px solid rgba(255,255,255,0.2)',
                  borderRadius: '8px',
                  color: '#fff',
                  height: 32,
                  width: 32,
                  '&:hover': { background: 'rgba(255,255,255,0.22)' },
                }}
              >
                <CloseIcon sx={{ fontSize: 16 }} />
              </IconButton>
            </Box>
          </Box>

          {/* ── Form content ──────────────────────────────────────── */}
          <DialogContent sx={{ p: 3 }}>
            <Grid container>
              <FieldItem label={t('product:title.name')}>
                <TextField
                  autoComplete="off"
                  fullWidth
                  placeholder={t('product:title.name')}
                  size="small"
                  {...formik.getFieldProps('name')}
                  sx={fieldSx}
                />
              </FieldItem>

              <FieldItem label="Mobile">
                <TextField
                  autoComplete="off"
                  fullWidth
                  placeholder="Mobile"
                  size="small"
                  {...formik.getFieldProps('mobile')}
                  sx={fieldSx}
                />
              </FieldItem>

              <FieldItem label="Address">
                <TextField
                  autoComplete="off"
                  fullWidth
                  placeholder="Address"
                  size="small"
                  {...formik.getFieldProps('address')}
                  sx={fieldSx}
                />
              </FieldItem>

              <FieldItem label="Date Of Birth">
                <LocalizationProvider dateAdapter={AdapterDayjs}>
                  <DatePicker
                    InputProps={{ sx: { height: '40px', ...fieldSx } }}
                    renderInput={(params) => (
                      <TextField
                        fullWidth
                        size="small"
                        {...params}
                        sx={fieldSx}
                      />
                    )}
                    {...formik.getFieldProps('dateOfBirth')}
                    inputFormat="DD-MM-YYYY"
                    onChange={(date) => {
                      formik.setFieldValue('dateOfBirth', date);
                    }}
                    views={['day', 'month', 'year']}
                  />
                </LocalizationProvider>
              </FieldItem>
            </Grid>
          </DialogContent>

          {/* ── Actions ───────────────────────────────────────────── */}
          <DialogActions sx={{ gap: 1.5, pb: 3, pt: 0, px: 3 }}>
            <Button
              fullWidth
              onClick={handleClose}
              sx={{
                borderColor: alpha(NAVY, 0.25),
                borderRadius: '10px',
                color: NAVY,
                fontWeight: 700,
                height: 44,
                '&:hover': {
                  background: alpha(NAVY, 0.04),
                  borderColor: alpha(NAVY, 0.5),
                },
              }}
              variant="outlined"
            >
              {t('common:cancel')}
            </Button>
            <Button
              autoFocus
              disabled={!formValid || isLoading}
              fullWidth
              onClick={() => { formik.handleSubmit(); }}
              sx={{
                background: formValid
                  ? `linear-gradient(135deg, ${TEAL} 0%, ${MID} 100%)`
                  : undefined,
                borderRadius: '10px',
                boxShadow: formValid
                  ? `0 4px 14px ${alpha(TEAL, 0.4)}`
                  : undefined,
                color: '#fff',
                fontWeight: 700,
                height: 44,
                '&:hover': {
                  background:
                    `linear-gradient(135deg, ${MID} 0%, ${NAVY} 100%)`,
                },
                '&:disabled': { opacity: 0.5 },
              }}
              type="submit"
              variant="contained"
            >
              {isLoading ? (
                <CircularProgress
                  size={18}
                  sx={{ color: '#fff' }}
                />
              ) : buttonText}
            </Button>
          </DialogActions>
        </Dialog>
      </form>
    </div>
  );
};

export default React.memo(NewPatient);

const fieldSx = {
  '& .MuiOutlinedInput-root': {
    backgroundColor: alpha(TEAL, 0.03),
    borderRadius: '8px',
    '& fieldset': { borderColor: alpha(TEAL, 0.2) },
    '&.Mui-focused fieldset': { borderColor: TEAL },
    '&:hover fieldset': { borderColor: alpha(TEAL, 0.4) },
  },
};

// eslint-disable-next-line react/no-multi-comp
const FieldItem = ({
  label,
  children,
}: {
  label: string;
  children: React.ReactNode;
}) => (
  <Grid
    item
    lg={12}
    sm={12}
    sx={{ pb: 2 }}
    xs={12}
  >
    <Typography
      sx={{
        color: alpha(NAVY, 0.5),
        fontSize: 11,
        fontWeight: 700,
        letterSpacing: '0.5px',
        mb: 0.75,
        textTransform: 'uppercase',
      }}
    >
      {label}
    </Typography>
    {children}
  </Grid>
);
